def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    rich_pressure = 0
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= 700:
                rich_pressure += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0.0)))
                except Exception:
                    pass

    if not alive_opps:
        return float(min(budget, 5.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 3
    elif supply <= 18:
        scarcity = 2
    elif supply <= 21:
        scarcity = 1

    danger = 0
    if hp <= 2:
        danger = 3
    elif hp <= 4 or no_water_days >= 1:
        danger = 2
    elif hp <= 6:
        danger = 1

    if danger >= 3:
        bid = max(0.95 * DAILY_SALARY, max_prev + 2.0)
    elif danger == 2:
        bid = max(0.78 * DAILY_SALARY, min(max_prev + 1.0, 0.92 * DAILY_SALARY))
    else:
        if scarcity >= 3:
            bid = max(0.72 * DAILY_SALARY, min(max_prev + 1.0, 0.9 * DAILY_SALARY))
        elif scarcity == 2:
            bid = max(0.52 * DAILY_SALARY, min(avg_prev * 0.7 + 4.0, 0.78 * DAILY_SALARY))
        elif scarcity == 1:
            bid = max(0.32 * DAILY_SALARY, min(avg_prev * 0.45 + 2.0, 0.58 * DAILY_SALARY))
        else:
            bid = 0.18 * DAILY_SALARY

    if rich_pressure >= 2 and danger == 0 and scarcity <= 1:
        bid *= 0.75

    if desperate_count >= 2 and (scarcity >= 2 or danger >= 1):
        bid += 6.0

    if day >= 8 and hp >= 5 and scarcity == 0:
        bid *= 0.8

    if budget < DAILY_SALARY:
        bid = min(bid, max(8.0, budget * 0.7))

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # React to yesterday bids of alive opponents (only immediate trace)
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Determine how aggressive the market was yesterday
    threshold = DAILY_SALARY * 0.85  # ~76.5
    aggressive = any(b >= threshold for b in prev_bids) if prev_bids else False
    max_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-pressure: with higher supply, winning is cheaper; with lower supply, bid more
    # Expected number of units roughly supply / WATER_REQ (but we only need a monotone scaling)
    # Ensure indices are safe (no indexing used here).
    supply_ratio = (supply - 15.0) / (25.0 - 15.0)  # 0..1
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid level
    if aggressive:
        # If they were already paying close to salary, we match moderately to secure our survival.
        base = DAILY_SALARY * (0.55 + 0.25 * (1.0 - supply_ratio))
        # If someone maxed yesterday, nudge up slightly but cap.
        if max_prev_bid > 0:
            base = max(base, min(my_budget, max_prev_bid * 0.85))
    else:
        base = DAILY_SALARY * (0.45 + 0.20 * (1.0 - supply_ratio))

    # Urgency from our hp / no-water streak
    urgency = 0.0
    if my_hp <= 2:
        urgency = 0.35
    elif my_hp <= 4:
        urgency = 0.22
    elif my_hp <= 6:
        urgency = 0.12
    else:
        urgency = 0.06

    if my_no_water_days >= 2:
        urgency += 0.15
    if my_no_water_days >= 4:
        urgency += 0.25

    target = base * (1.0 + urgency)

    # If day is late, slightly increase to avoid running out
    if day >= 8:
        target *= 1.08

    # Final caps: cannot exceed budget; also avoid overpaying beyond what likely wins
    # Use a soft cap near salary since bids seem around 90-120.
    soft_cap = DAILY_SALARY * 1.35
    target = min(target, soft_cap)

    # Ensure non-negative and within budget
    bid = max(0.0, min(my_budget, target))

    # If our budget is very low, still try to bid something only when critical
    if my_budget < DAILY_SALARY * 0.2:
        if my_hp <= 3 or my_no_water_days >= 3:
            bid = max(0.0, min(my_budget, DAILY_SALARY * 0.25))
        else:
            bid = max(0.0, min(my_budget, DAILY_SALARY * 0.1))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return int(min(my_status['budget'], DAILY_SALARY * 0.4))
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 85
    if my_status['hp'] <= 3:
        return int(min(my_status['budget'], DAILY_SALARY * 1.2))
    if day_context['supply'] < WATER_REQ * 2:
        return int(min(my_status['budget'], avg_prev_bid * 1.1))
    return int(min(my_status['budget'], avg_prev_bid * 0.95))
